const fs=require('fs');
const emitted=fs.readFileSync('emitted.txt','utf8').trim().split('\n');
// normalize a decimal string to [sign, digitsNoLeadTrailZero, decpt]
function norm(s){
  let sign=1; if(s[0]==='-'){sign=-1;s=s.slice(1);} else if(s[0]==='+'){s=s.slice(1);}
  let exp=0; const ei=s.toLowerCase().indexOf('e');
  if(ei>=0){exp=parseInt(s.slice(ei+1),10); s=s.slice(0,ei);}
  let ip=s, fp=''; const di=s.indexOf('.');
  if(di>=0){ip=s.slice(0,di); fp=s.slice(di+1);}
  let digits=(ip+fp).replace(/^0+/,'');
  let decpt=ip.replace(/^0+/,'').length+exp;
  if(ip.replace(/^0+/,'').length===0){ // 0.000ddd
    const lead=(fp.match(/^0*/)||[''])[0].length;
    digits=fp.slice(lead); decpt=-lead+exp;
  }
  digits=digits.replace(/0+$/,'');
  if(digits===''){digits='0';decpt=0;}
  return sign+'|'+digits+'|'+decpt;
}
let mism=0;
for(const e of emitted){
  const v=Number(e);
  const a=norm(e), b=norm(String(v));
  if(a!==b){mism++; console.log('DIGIT MISMATCH', e, String(v), a, b);}
}
console.log('checked',emitted.length,'digit-level mismatches:',mism);
